import React, { useState } from 'react';

const Home = () => {
  // 1. TA LISTE DE COURS (Très facile à modifier ou à agrandir devant le prof)
  const [courses, setCourses] = useState([
    { id: 1, title: "Hacking Éthique & Pentest : Les Fondations", level: "Débutant", price: 25000, isFree: false },
    { id: 2, title: "Sécurisation des Architectures Réseaux & pfSense", level: "Avancé", price: 40000, isFree: false },
    { id: 3, title: "Introduction à la Cybersécurité et Hygiène Numérique", level: "Débutant", price: 0, isFree: true }
  ]);

  // 2. LES VARIABLES D'ÉTAT (LES STATES BASIQUES)
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCourse, setSelectedCourse] = useState(null);
  const [paymentMethod, setPaymentMethod] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [paymentSuccess, setPaymentSuccess] = useState(false);

  // 3. LA SIMULATION DU PAIEMENT (Un simple setTimeout de 3 secondes)
  const déclencherPaiementSimulé = (e) => {
    e.preventDefault();
    setIsProcessing(true);

    setTimeout(() => {
      setIsProcessing(false);
      setPaymentSuccess(true);
    }, 3000);
  };

  return (
    <div className="min-h-screen bg-[#030712] text-gray-100 font-sans">
      
      {/* BARRE DE NAVIGATION (Thème Sombre et Bleu) */}
      <header className="border-b border-slate-800 bg-gray-900 px-6 py-4 flex justify-between items-center">
        <h1 className="text-xl font-bold text-blue-500">Avalon Secure Academy</h1>
        <div className="flex gap-4">
          <a href="/login" className="text-gray-400 hover:text-white text-sm self-center">Se connecter</a>
          <a href="/register" className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-blue-500">
            S'inscrire
          </a>
        </div>
      </header>

      {/* CONTENU PRINCIPAL */}
      <main className="max-w-6xl mx-auto px-4 py-12">
        
        {/* TITRES */}
        <div className="text-center mb-12">
          <h2 className="text-4xl font-extrabold mb-4">Maîtrisez la Cybersécurité et les Réseaux</h2>
          <p className="text-gray-400 text-lg">Des formations pratiques et universelles. Accès à vie.</p>
        </div>

        {/* BARRE DE RECHERCHE SIMPLE */}
        <div className="bg-gray-900 border border-slate-800 rounded-xl p-4 mb-10">
          <input
            type="text"
            placeholder="Rechercher un cours..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full bg-[#030712] border border-slate-800 rounded-lg px-4 py-2 text-gray-200 focus:outline-none focus:border-blue-500"
          />
        </div>

        {/* GRILLE DES COURS */}
        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
          {courses
            .filter(c => c.title.toLowerCase().includes(searchQuery.toLowerCase()))
            .map((course) => (
              <div key={course.id} className="bg-gray-900 border border-slate-800 rounded-xl p-5 flex flex-col justify-between">
                
                <div>
                  <div className="flex justify-between items-center mb-4">
                    <span className="bg-slate-800 text-blue-400 text-xs px-2.5 py-1 rounded-full font-semibold">
                      {course.level}
                    </span>
                    {course.isFree && (
                      <span className="bg-blue-500/20 text-blue-400 text-xs px-2.5 py-1 rounded-full font-bold border border-blue-500/30">
                        Gratuit
                      </span>
                    )}
                  </div>
                  <h3 className="text-lg font-bold mb-4">{course.title}</h3>
                </div>
                
                <div>
                  <p className="text-xl font-black text-blue-400 mb-4">
                    {course.isFree ? "0 FCFA" : `${course.price.toLocaleString()} FCFA`}
                  </p>
                  
                  {course.isFree ? (
                    <button
                      onClick={() => alert('Accès débloqué pour ce cours gratuit !')}
                      className="w-full bg-blue-600 hover:bg-blue-500 text-white font-bold py-2 rounded-lg text-sm"
                    >
                      Suivre gratuitement
                    </button>
                  ) : (
                    <button
                      onClick={() => {
                        setSelectedCourse(course);
                        setPaymentMethod('');
                        setPaymentSuccess(false);
                      }}
                      className="w-full bg-slate-950 hover:bg-slate-800 text-gray-200 border border-slate-800 font-bold py-2 rounded-lg text-sm"
                    >
                      Acheter le cours
                    </button>
                  )}
                </div>

              </div>
            ))}
        </div>
      </main>

      {/* MODAL DE PAIEMENT SIMULÉ */}
      {selectedCourse && (
        <div className="fixed inset-0 bg-black/80 flex items-center justify-center p-4">
          <div className="w-full max-w-md bg-gray-900 border border-slate-800 rounded-xl p-6 relative">
            
            {/* Bouton pour fermer */}
            <button onClick={() => setSelectedCourse(null)} className="absolute top-4 right-4 text-gray-400 hover:text-white">
              ✕
            </button>

            {!paymentSuccess ? (
              <>
                <h3 className="text-lg font-bold mb-1">Finaliser votre achat</h3>
                <p className="text-sm text-gray-400 mb-4">{selectedCourse.title}</p>
                
                <div className="bg-[#030712] p-3 rounded-lg border border-slate-800 flex justify-between items-center mb-6">
                  <span className="text-sm text-gray-400">Prix unique :</span>
                  <span className="text-xl font-bold text-blue-400">{selectedCourse.price.toLocaleString()} FCFA</span>
                </div>

                <form onSubmit={déclencherPaiementSimulé} className="space-y-6">
                  
                  {/* Les 4 boutons de paiement */}
                  <div className="grid grid-cols-2 gap-3">
                    <button
                      type="button"
                      onClick={() => setPaymentMethod('mtn')}
                      className={`p-3 rounded-lg border text-sm font-bold ${paymentMethod === 'mtn' ? 'border-blue-500 bg-blue-500/10 text-blue-400' : 'border-slate-800 bg-[#030712]'}`}
                    >
                      MTN MoMo
                    </button>

                    <button
                      type="button"
                      onClick={() => setPaymentMethod('wave')}
                      className={`p-3 rounded-lg border text-sm font-bold ${paymentMethod === 'wave' ? 'border-blue-500 bg-blue-500/10 text-blue-400' : 'border-slate-800 bg-[#030712]'}`}
                    >
                      Wave
                    </button>

                    <button
                      type="button"
                      onClick={() => setPaymentMethod('card')}
                      className={`p-3 rounded-lg border text-sm font-bold ${paymentMethod === 'card' ? 'border-blue-500 bg-blue-500/10 text-blue-400' : 'border-slate-800 bg-[#030712]'}`}
                    >
                      Carte Bancaire
                    </button>

                    <button
                      type="button"
                      onClick={() => setPaymentMethod('paypal')}
                      className={`p-3 rounded-lg border text-sm font-bold ${paymentMethod === 'paypal' ? 'border-blue-500 bg-blue-500/10 text-blue-400' : 'border-slate-800 bg-[#030712]'}`}
                    >
                      PayPal
                    </button>
                  </div>

                  {/* Bouton de validation ou Faux chargement */}
                  {isProcessing ? (
                    <div className="w-full text-center py-3 bg-slate-950 border border-slate-800 rounded-lg text-xs text-gray-400">
                      Chargement sécurisé...
                    </div>
                  ) : (
                    <button
                      type="submit"
                      disabled={!paymentMethod}
                      className={`w-full py-3 rounded-lg font-bold ${paymentMethod ? 'bg-blue-600 text-white' : 'bg-gray-800 text-gray-500'}`}
                    >
                      Simuler le paiement
                    </button>
                  )}

                </form>
              </>
            ) : (
              /* ÉCRAN DE SUCCÈS */
              <div className="text-center py-6">
                <div className="text-blue-500 text-4xl mb-3">🎉</div>
                <h3 className="text-2xl font-bold mb-2">Paiement validé !</h3>
                <p className="text-gray-400 text-sm mb-6">Le cours a été ajouté à votre espace.</p>
                <button
                  onClick={() => setSelectedCourse(null)}
                  className="w-full bg-blue-600 text-white font-bold py-2 rounded-lg"
                >
                  Ouvrir la formation
                </button>
              </div>
            )}

          </div>
        </div>
      )}

    </div>
  );
};

export default Home;
